{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Across all four datasets, constrain every nonpadding embedding, including the exclusive mask embedding, to the expected initial Xavier row norm. Use the same effective tied table for context, masked-item cross-entropy and candidate scoring. This tests angular discrimination while preserving width, topology, loss, optimizer and histories. The generated predictor imports the updated model class, preserving checkpoint and inference consistency.",
      "edits": [
        {
          "find": "        masked_states, model.item_emb.weight[1:model.itemnum + 1]\n",
          "replace": "        masked_states, model.effective_item_weight()[1:model.itemnum + 1]\n"
        },
        {
          "find": "    def encode_sequence(self, seq: torch.Tensor) -> torch.Tensor:\n",
          "replace": "    def effective_item_weight(self) -> torch.Tensor:\n        row_norm = math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))\n        nonpadding = torch.nn.functional.normalize(\n            self.item_emb.weight[1:], p=2, dim=-1, eps=1e-12\n        ) * row_norm\n        return torch.cat((torch.zeros_like(self.item_emb.weight[:1]), nonpadding), dim=0)\n\n    def encode_sequence(self, seq: torch.Tensor) -> torch.Tensor:\n"
        },
        {
          "find": "        x = self.item_emb(seq) * (self.hidden_units ** 0.5) + self.pos_emb(pos)\n",
          "replace": "        item_vectors = torch.nn.functional.embedding(\n            seq, self.effective_item_weight(), padding_idx=0\n        )\n        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)\n"
        },
        {
          "find": "        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.item_emb(neg)).sum(dim=-1)\n",
          "replace": "        item_weight = self.effective_item_weight()\n        pos_scores = (out * torch.nn.functional.embedding(pos, item_weight, padding_idx=0)).sum(dim=-1)\n        neg_scores = (out * torch.nn.functional.embedding(neg, item_weight, padding_idx=0)).sum(dim=-1)\n"
        },
        {
          "find": "        cand_emb = self.item_emb(candidates)\n",
          "replace": "        cand_emb = torch.nn.functional.embedding(\n            candidates, self.effective_item_weight(), padding_idx=0\n        )\n"
        }
      ]
    }
  ],
  "change_summary": "Normalize the tied BERT4Rec item table to a fixed Xavier-scale row norm across context lookup, training logits and candidate scoring. Preserve zero padding, the exclusive mask ID and existing checkpoint shapes; the embedded predictor automatically imports the updated implementation."
}
